pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint64 targetGasWaste) public {
        // restrict amount to avoid overflow and stay in a wide admissible range
        vm.assume(amount <= 1000 ether);

        // deploy an adversarial target that wastes a variable amount of gas before returning,
        // so the target call succeeds but may not consume all forwarded Ether
        GasWaster waster = new GasWaster(targetGasWaste);
        // make the target address receive the call (the code is at that address)
        vm.etch(0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C, address(waster).code);

        // fund the caller
        address actor = makeAddr("actor");
        vm.deal(actor, amount);

        // call go
        vm.prank(actor);
        c.go{value: amount}();

        // rule: after any call to go, the contract's own balance must be zero
        assertTrue(address(c).balance == 0, "contract balance not zero after go()");
    }
}

contract GasWaster {
    uint256 waste;
    constructor(uint256 _waste) { waste = _waste; }
    fallback() external payable {
        // waste a variable amount of gas to emulate a target that does not consume all forwarded Ether
        for (uint256 i = 0; i < waste; i++) {
            assembly { pop(0) }
        }
    }
}

