pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address ownerAddr) public {
        // Bound amount to avoid overflow and keep it admissible
        amount = bound(amount, 0, address(c).balance);
        vm.deal(address(c), amount + 1 ether);

        // Ensure owner is a contract that cannot receive Ether, to trigger the bug
        vm.assume(ownerAddr.code.length > 0);
        vm.assume(ownerAddr != address(c));
        vm.assume(ownerAddr != address(this));

        // Deploy a helper that always reverts on receive, and set it as owner
        RevertingReceiver helper = new RevertingReceiver();
        c = new C();
        // We can't change owner directly without a setter, so we prank as the owner-to-be
        vm.prank(address(helper));
        c = new C(); // Deploy c so that owner is the helper contract

        // Fund the helper to act as msg.sender
        vm.deal(address(helper), amount + 2 ether);

        // Execute go() as the owner (helper contract)
        vm.prank(address(helper));
        c.go{value: amount}();

        // After execution, the reference's transfer would revert entirely, so balance would be non-zero
        // but in practice the call to target succeeds and then transfer to owner reverts, leaving balance.
        // The mutant's send would silently fail, also leaving balance.
        // The property: balance must be zero after successful go() — this holds for reference (never succeeds with adversarial owner), and fails for mutant (succeeds but leaves balance > 0)
        // Actually: reference reverts entirely with adversary owner, so the transaction fails — no state change.
        // To make reference pass: we need owner to be an EOA so transfer succeeds.
        // Let's adjust: test that after go() is called, if it doesn't revert, balance must be zero.
        // Reference with EOA owner: succeeds, balance == 0.
        // Mutant with adversarial owner: succeeds (send doesn't revert), balance > 0.
        // So we need to fuzz whether owner is adversarial (code) or not.
        // Simpler: always use an adversarial owner for the bug to manifest.
        // But then reference would revert -> we need to catch that.
        // The rule: if go() does not revert, the contract balance must be zero.

        bool ok;
        uint256 balBefore = address(c).balance;
        try c.go{value: amount}() { ok = true; } catch { ok = false; }
        uint256 balAfter = address(c).balance;

        // Property: (ok == true) => (balAfter == 0)
        // Reference: ok=false always when owner is adversarial (transfer reverts), so implication vacuously true.
        // Mutant: ok=true (send doesn't revert), balAfter > 0, so implication fails.
        assertTrue(!ok || balAfter == 0);
    }
}

contract RevertingReceiver {
    fallback() external payable {
        revert();
    }
}

