contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound to sensible range; assume non-zero to trigger bug
        vm.assume(amount > 0);
        amount = bound(amount, 1, type(uint64).max);

        // Deploy adversarial recipient that reverts on receive
        RevertingReceiver receiver = new RevertingReceiver();
        address caller = address(receiver);

        // Fund the caller with sent amount
        vm.deal(caller, amount);

        // Record owner's balance before
        uint256 ownerBalanceBefore = c.owner().balance;

        // Call go() from the adversarial caller, sending amount
        vm.prank(caller);
        c.go{value: amount}();

        // Owner's balance must NEVER change in the reference.
        // In the mutant, owner does not receive the final transfer;
        // however, because the target call consumes msg.value and the final
        // transfer to msg.sender reverts, the contract balance would remain.
        // But the bug is that msg.sender receives the transfer instead of owner.
        // Since msg.sender is the reverting receiver, the transfer to msg.sender
        // also reverts, leaving contract balance > 0. In the reference, owner's
        // balance remains unchanged because the call consumes msg.value and the
        // remaining balance (0) is transferred to owner, so owner's balance doesn't change.
        // The invariant: owner's balance before and after is the same in the reference.
        assertEq(c.owner().balance, ownerBalanceBefore, "owner balance should never change");
    }
}

